/** Exact saved-map codec and real table/Screen cooperative raster path; never loads the sampled terrain. */
public final class NativeSavedMapChecks {
 private static int checks;
 public static void run(ServerLevel world,ServerPlayer actor)throws Exception{
  int[] palette=new int[256];for(int i=0;i<256;i++)palette[i]=0xff000000|i*65793;palette[0]=0;
  byte[] colors=new byte[16384];for(int z=0;z<128;z++)for(int x=0;x<128;x++)colors[z*128+x]=(byte)((x+z)%3==0?0:1+(x+3*z)%255);
  // Deliberately far from loaded fixtures, with a scale4 square extending past the pin circle.
  var map=new SavedMapPixels(NativeNavigationChip.dimension(world),900000,800000,4,colors,palette);var chip=NativeChipTypes.variant("navigation");NativeNavigationChip.write(chip,world,map.centerX(),map.centerZ());var tag=chip.get(DataComponents.CUSTOM_DATA).copyTag();tag.putString("PrivateCompany","retained");tag.putString("VehicleDesign","stale");tag.putString("CatalogName","stale");tag.getCompound("NavigationLocation").putInt("Y",123);chip.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));NativeNavigationChip.writeMap(chip,map);
  need(map.equals(NativeNavigationChip.savedMap(chip)),"native map exact codec roundtrip");need(!chip.get(DataComponents.CUSTOM_DATA).copyTag().contains("VehicleDesign")&&!chip.get(DataComponents.CUSTOM_DATA).copyTag().contains("CatalogName"),"navigation write removes stale type payloads");need(NativeNavigationChip.location(chip).getInt("Y")==123&&chip.get(DataComponents.CUSTOM_DATA).copyTag().getString("PrivateCompany").equals("retained"),"map write preserves Y/company");
  var saved=ItemStack.parse(world.registryAccess(),chip.save(world.registryAccess())).orElseThrow();need(map.equals(NativeNavigationChip.savedMap(saved))&&ItemStack.matches(chip,saved),"full item save/reload keeps exact arrays");
  var before=chip.copy();var summary=NativeNavigationChip.summary(chip);var projected=summary.get(DataComponents.CUSTOM_DATA).copyTag().getCompound("NavigationMapPixels");need(!projected.contains("Colors")&&!projected.contains("Palette")&&projected.getInt("Hash")==map.hash()&&projected.getInt("Scale")==4,"update strips only arrays");need(ItemStack.matches(before,chip)&&NativeNavigationChip.savedMap(summary)==null,"public copy never changes inventory and cannot seed a fake map");
  int fullBytes=bytes(world,chip),publicBytes=bytes(world,summary);need(fullBytes>17500&&publicBytes<1000,"map public update byte reduction");System.out.println("[vandorlabs][saved-map] bytes full="+fullBytes+" public="+publicBytes);
  for(int fault=0;fault<7;fault++){var bad=chip.copy();var root=bad.get(DataComponents.CUSTOM_DATA).copyTag();var payload=root.getCompound("NavigationMapPixels");switch(fault){case 0->payload.putInt("Hash",map.hash()+1);case 1->payload.putInt("Version",2);case 2->payload.putByteArray("Colors",new byte[16383]);case 3->payload.putIntArray("Palette",new int[255]);case 4->payload.putString("Scale","4");case 5->payload.putInt("Scale",5);case 6->payload.putInt("CenterX",map.centerX()+1);}bad.set(DataComponents.CUSTOM_DATA,CustomData.of(root));var exact=bad.copy();need(NativeNavigationChip.savedMap(bad)==null&&ItemStack.matches(exact,bad),"malformed snapshot retained fault="+fault);}
  var cleared=chip.copy();NativeNavigationChip.write(cleared,world,1,2);need(NativeNavigationChip.savedMap(cleared)==null&&!cleared.get(DataComponents.CUSTOM_DATA).copyTag().contains("NavigationMapPixels"),"normal location write clears snapshot");
  var tablePos=new BlockPos(46,120,46);world.setBlock(tablePos,NativeNavigationTableBindings.FLAT.defaultBlockState(),3);var table=(NativeNavigationTableEntity)world.getBlockEntity(tablePos);NativeNavigationTableAssemblies.rebuild(table,new HashSet<>());table.setChip(chip);need(map.equals(NativeNavigationRuntime.overrideMapSnapshot(table,0)),"table receives saved map");tableProjection(world,table,map);raster(world,actor,table,map);var priorPosition=actor.position();actor.setPos(tablePos.getX()+.5,tablePos.getY()+1,tablePos.getZ()+.5);var view=NativeNavigationRuntime.view(table);view.x=map.minX()+1;view.z=map.minZ()+1;need(!NavigationMap.covers(view.x,view.z,map.centerX(),map.centerZ(),1000)&&NativeNavigationRuntime.action(actor,table,7),"actual table writes pin inside snapshot square beyond old circle");need(NativeNavigationChip.savedMap(table.chipStack())==null&&NativeNavigationChip.location(table.chipStack()).getInt("X")==map.minX()+1,"SET replaces snapshot with new exact pin");table.setChip(chip);actor.setPos(priorPosition.x,priorPosition.y,priorPosition.z);
  var screenPos=tablePos.above(2);var block=(NativeScreenBlock)BuiltInRegistries.BLOCK.get(ResourceLocation.parse("vandorlabs:programmable_diagonal_screen"));world.setBlock(screenPos,block.defaultBlockState(),3);var screen=(NativeScreenEntity)world.getBlockEntity(screenPos);var data=screen.saveWithoutMetadata(world.registryAccess());data.putInt("PrimarySurfaceTexture",-5);var reader=new CompoundTag();reader.put("InsertedToken",chip.save(world.registryAccess()));data.put("ScreenChipReader",reader);screen.loadWithComponents(data,world.registryAccess());need(!screen.inert()&&map.equals(NativeNavigationRuntime.overrideMapSnapshot(screen,0)),"integrated Screen receives exact saved map");var screenPublic=screen.getUpdateTag(world.registryAccess());need(!screenPublic.contains("ScreenChipReader")&&!hasMapArrays(screenPublic),"actual Screen public update contains neither private reader nor map pixel arrays");need(map.equals(NativeNavigationChip.savedMap(NativeScreenNavigation.chipStack(screen))),"Screen public update leaves private original map intact");raster(world,actor,screen,map);
  need(world.getChunkSource().getChunkNow(map.centerX()>>4,map.centerZ()>>4)==null&&world.getChunkSource().getChunkNow(map.minX()>>4,map.minZ()>>4)==null,"saved-map raster requests no sampled chunks");world.removeBlock(screenPos,false);world.removeBlock(tablePos,false);
  journal(world,chip);
  System.out.println("[vandorlabs][saved-map] PASS checks="+checks+" exactCodec/privateProjection/tamper/table+Screen/scale4OutsidePin/blank/noChunks");
 }
 private static void tableProjection(ServerLevel world,NativeNavigationTableEntity table,SavedMapPixels map)throws java.io.IOException{
  var original=table.chipStack().copy();var update=table.getUpdateTag(world.registryAccess());var projectedChip=ItemStack.parse(world.registryAccess(),update.getCompound("NavigationChip")).orElseThrow();var projected=projectedChip.get(DataComponents.CUSTOM_DATA).copyTag().getCompound("NavigationMapPixels");need(!projected.contains("Colors")&&!projected.contains("Palette")&&!hasMapArrays(update),"actual table update omits map arrays");need(projected.getInt("Hash")==map.hash()&&projected.getInt("Scale")==map.scale()&&NativeNavigationChip.location(projectedChip).getInt("X")==map.centerX()&&NativeNavigationChip.location(projectedChip).getInt("Z")==map.centerZ(),"actual table update keeps hash/scale/exact point");
  var saved=table.saveWithoutMetadata(world.registryAccess());var savedChip=ItemStack.parse(world.registryAccess(),saved.getCompound("NavigationChip")).orElseThrow();need(map.equals(NativeNavigationChip.savedMap(savedChip))&&ItemStack.matches(original,table.chipStack())&&map.equals(NativeNavigationChip.savedMap(table.chipStack())),"public table update preserves full save and inventory exact pixels");
  var baseline=update.copy();baseline.put("NavigationChip",original.save(world.registryAccess()));int before=tagBytes(baseline),after=tagBytes(update);need(before-after>17400&&after<2000,"actual table update reduction replaces full chip with summary");System.out.println("[vandorlabs][saved-map] table update bytes fullBaseline="+before+" actualPublic="+after+" privateSave="+tagBytes(saved));
 }
 private static boolean hasMapArrays(Tag tag){if(tag instanceof CompoundTag c){if(c.contains("NavigationMapPixels",Tag.TAG_COMPOUND)){var pixels=c.getCompound("NavigationMapPixels");if(pixels.contains("Colors")||pixels.contains("Palette"))return true;}for(String key:c.getAllKeys())if(hasMapArrays(c.get(key)))return true;}else if(tag instanceof ListTag list){for(Tag child:list)if(hasMapArrays(child))return true;}return false;}
 private static int tagBytes(CompoundTag tag)throws java.io.IOException{var out=new java.io.ByteArrayOutputStream();NbtIo.write(tag,new java.io.DataOutputStream(out));return out.size();}
 private static void journal(ServerLevel world,ItemStack mapChip){
  var chip=mapChip.copy();NativeChipJournal.write(chip,true,"Ancient text",new String[]{"Hidden words","Second page"});var tag=chip.get(DataComponents.CUSTOM_DATA).copyTag();need(!tag.contains("NavigationLocation")&&!tag.contains("NavigationMapPixels"),"journal programming clears old map/location");tag.putString("JournalFont","enchanting");tag.putString("PrivateScanSource","not public");chip.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));var projection=NativeChipJournal.textData(chip);need(NativeChipJournal.enchanting(projection)&&!projection.contains("PrivateScanSource"),"enchanting journal projection allowlists exact font");
  var raw=new CompoundTag();raw.put("InsertedToken",chip.save(world.registryAccess()));var reader=NativeEmbeddedChipReader.storage(raw,world.registryAccess());var view=NativeScreenChipView.of(reader,world.getGameTime(),0);need(view.enchanting()&&NativeScreenChipView.read(view.write()).enchanting(),"Screen journal font roundtrip");var bad=view.write();bad.getCompound("Journal").putString("JournalFont","unknown");boolean rejected=false;try{NativeScreenChipView.read(bad);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"Screen rejects unknown journal font");
  var programmer=com.vandorlabs.neoforge.programmer.NativeProgrammerJournalView.prepare(ItemStack.EMPTY,chip,com.vandorlabs.neoforge.programmer.NativeProgrammerDraft.empty());need(programmer!=null&&programmer.enchanting&&com.vandorlabs.neoforge.programmer.NativeProgrammerJournalView.read(programmer.write()).enchanting,"Programmer output journal font roundtrip");
  NativeChipJournal.write(chip,true,"Edited text",new String[]{"Normal font"});need(!chip.get(DataComponents.CUSTOM_DATA).copyTag().contains("JournalFont"),"ordinary Journal edit clears enchanting flag");var copiedMap=mapChip.copy();NativeNavigationChip.writeMap(chip,NativeNavigationChip.savedMap(copiedMap));need(!chip.get(DataComponents.CUSTOM_DATA).copyTag().contains("JournalPages")&&!chip.get(DataComponents.CUSTOM_DATA).copyTag().contains("JournalFont"),"map programming clears journal payload");
 }
 private static void raster(ServerLevel world,ServerPlayer actor,BlockEntity tile,SavedMapPixels map)throws Exception{
  Class<?> runtime=NativeNavigationRuntime.class;var host=runtime.getDeclaredMethod("host",BlockEntity.class,int.class);host.setAccessible(true);Object h=host.invoke(null,tile,0);var terrain=runtime.getDeclaredMethod("terrain",ServerLevel.class);terrain.setAccessible(true);Object sampler=terrain.invoke(null,world);var canvas=new NavigationCanvas(256,256,false);int x=map.minX()+64,z=map.minZ()+64,zoom=0;
  Class<?> keyClass=Class.forName(runtime.getName()+"$RasterKey");var keyCtor=keyClass.getDeclaredConstructors()[0];keyCtor.setAccessible(true);Object key=keyCtor.newInstance(world,sampler,x,z,zoom,canvas.width,canvas.height,canvas.mapBottom,canvas.progressive,List.of(),map,NavigationSurface.View.EMPTY);
  Class<?> jobClass=Class.forName(runtime.getName()+"$Job");var ctor=jobClass.getDeclaredConstructors()[0];ctor.setAccessible(true);Object job=ctor.newInstance(actor,h,new NativeNavigationPayload(tile.getBlockPos(),0,1,0,0),key,canvas,false,false,null);var sample=jobClass.getDeclaredMethod("sample");sample.setAccessible(true);var pixelsField=jobClass.getDeclaredField("pixels");pixelsField.setAccessible(true);int[] pixels=(int[])pixelsField.get(job);long terrainBefore=NativeNavigationRuntime.terrainSamples();int blanks=0,outsidePin=0;
  for(int i=0;i<pixels.length;i++){sample.invoke(job);int wx=canvas.sampleX(x,zoom,i%canvas.gridWidth(zoom)),wz=canvas.sampleZ(z,zoom,i/canvas.gridWidth(zoom));need(map.contains(wx,wz)&&pixels[i]==map.colorAt(wx,wz),"actual "+tile.getClass().getSimpleName()+" snapshot raster precedence");if(pixels[i]==0)blanks++;if(!NavigationMap.covers(wx,wz,map.centerX(),map.centerZ(),1000))outsidePin++;}
  need(blanks>0&&outsidePin==pixels.length,"blank pixels and full sampled corner outside pin preserved");need(NativeNavigationRuntime.terrainSamples()==terrainBefore,"snapshot raster skips terrain sampling");
 }
 private static int bytes(ServerLevel world,ItemStack stack)throws java.io.IOException{var out=new java.io.ByteArrayOutputStream();NbtIo.write((CompoundTag)stack.save(world.registryAccess()),new java.io.DataOutputStream(out));return out.size();}
 private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 private NativeSavedMapChecks(){}
}
